const items = $input.all();
const results = [];
for (const item of items) {
  const binaryKeys = Object.keys(item.binary || {});
  for (const key of binaryKeys) {
    const bin = item.binary[key];
    if (bin.mimeType === 'application/pdf' || bin.fileName.endsWith('.pdf')) {
      results.push({ json: { fileKey: key, fileName: bin.fileName, mimeType: bin.mimeType } });
    }
  }
}
if (results.length === 0) {
  results.push({ json: { error: 'No PDF files detected in upload' } });
}
return results;

const items = $input.all();
const results = [];
for (const item of items) {
  const text = item.json.ParsedResults?.[0]?.ParsedText || '';
  const invoiceNum = (text.match(/Invoice\s*#?\s*:?\s*(\S+)/i) || [])[1] || 'UNKNOWN';
  const dateMatch = (text.match(/(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4})/) || [])[1] || 'UNKNOWN';
  const totalMatch = (text.match(/Total\s*:?\s*\$?([\d,]+\.?\d*)/) || [])[1] || '0';
  const vendorMatch = (text.match(/From\s*:?\s*(.+)/i) || [])[1] || 'UNKNOWN';
  results.push({
    json: {
      invoiceNumber: invoiceNum,
      date: dateMatch,
      total: parseFloat(totalMatch.replace(/,/g, '')),
      vendor: vendorMatch.trim(),
      rawText: text.substring(0, 500),
      fileName: item.json.fileName || 'unknown.pdf'
    }
  });
}
return results;

